 static T Field<T>(object o,string n){return(T)o.GetType().GetField(n,F).GetValue(o);}static void Call(object o,string name,params object[] args){o.GetType().GetMethods(F).First(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);}
 static void Pump(int ms=300){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<end);}
 static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(var row in Walk(child))yield return row;}
 static bool Inside(Control c){if(c.Parent==null)return true;Rectangle rect=c.Bounds;return rect.Left>=-1&&rect.Top>=-1&&rect.Right<=c.Parent.ClientSize.Width+1&&rect.Bottom<=c.Parent.ClientSize.Height+1;}
 static bool AncestorsInside(Control c){while(c.Parent!=null){if(!Inside(c))return false;c=c.Parent;}return true;}
 static bool RenderedInside(Control c){if(!c.Visible)return false;var rect=new Rectangle(c.PointToScreen(Point.Empty),c.ClientSize);for(var parent=c.Parent;parent!=null;parent=parent.Parent)if(!new Rectangle(parent.PointToScreen(Point.Empty),parent.ClientSize).Contains(rect))return false;return true;}
 static void CompactScreen(MainForm f,bool dark){foreach(int mode in new[]{0,2}){f.SetWorkspaceLayout(mode,false);Pump();Check(f.Width==1920&&f.Height==1040&&f.MinimumSize.Width<=1920&&f.MinimumSize.Height<=1040,"Startup screen clamp uses the controlled1920x1040 working area / "+dark+" / "+mode);var top=Walk(f).Where(c=>c.Name.StartsWith("Task",StringComparison.Ordinal)||c.Name=="QuickCommands").ToArray();Check(top.Length==7&&top.All(RenderedInside),"All seven task commands are fully visible on the clamped screen / "+dark+" / "+mode);Check(Walk(f).Where(c=>c.Visible&&(c.Name=="QuickSave"||c.Text=="Verifica"||c.Text=="Esegui"||c.Text=="Avanti"||c.Text=="Esporta")).All(RenderedInside),"Frequent save, export and run actions remain visible / "+dark+" / "+mode);Check(Walk(f).Where(c=>c.Name=="ActiveDiagram"||c.Name=="ManageFunctions"||c.Name=="WorkspaceLayout").All(RenderedInside),"Diagram, functions and workspace choices remain visible / "+dark+" / "+mode);var view=Walk(f).Where(c=>c is Button&&(c.Text=="Inquadra"||c.Text=="Riordina"||c.Text=="−"||c.Text=="+"||c.AccessibleName=="Snap alla griglia attivo")).ToArray();var required=view.Where(c=>c.Visible).ToArray();var focus=Field<FlowButton>(f,"focusCanvasButton");Check(required.Any(c=>c.Text=="Inquadra")&&required.Any(c=>c.Text=="−")&&required.Any(c=>c.Text=="+")&&required.All(RenderedInside)&&RenderedInside(focus)&&required.All(c=>!new Rectangle(c.PointToScreen(Point.Empty),c.Size).IntersectsWith(new Rectangle(focus.PointToScreen(Point.Empty),focus.Size))),"Zoom, Inquadra and F8 remain visible without overlap; duplicates remain in Vista / "+dark+" / "+mode);Check(f.Canvas.Width>=250&&f.Canvas.Height>=200,"Canvas retains an editable area on clamped screen / "+dark+" / "+mode);Check(RenderedInside(Field<FlowButton>(f,"applyButton")),"Inspector confirmation stays visible on clamped screen / "+dark+" / "+mode);var inspector=Field<FlowScrollPanel>(f,"inspector");var expression=Field<TextBox>(f,"expression");inspector.ScrollControlIntoView(expression);Pump();expression.Focus();expression.SelectionStart=expression.TextLength;Pump();var caret=expression.PointToScreen(expression.GetPositionFromCharIndex(expression.SelectionStart));var viewport=new Rectangle(inspector.PointToScreen(Point.Empty),inspector.ClientSize);Check(expression.Focused&&viewport.Contains(caret)&&expression.Height>=30,"Inspector condition caret can be scrolled into view and focused / "+dark+" / "+mode);int historyCount=Field<System.Collections.ICollection>(f,"undo").Count;string oldText=expression.Text,modelText=f.Document.Nodes.Single(n=>n.Id=="check").Text;expression.Select(0,0);EditMessage(expression.Handle,0x00C2,new IntPtr(1),"1 + ");expression.Select(2,3);string draft=expression.Text;int start=expression.SelectionStart,length=expression.SelectionLength;var oldSize=f.Size;f.Height+=120;Pump();f.Size=oldSize;Pump();Check(expression.Text==draft&&expression.SelectionStart==start&&expression.SelectionLength==length&&expression.CanUndo&&Field<System.Collections.ICollection>(f,"undo").Count==historyCount&&f.Document.Nodes.Single(n=>n.Id=="check").Text==modelText,"Resize preserves condition draft, selection, native Undo and project history / "+dark+" / "+mode);expression.Undo();Pump();Check(expression.Text==oldText&&RenderedInside(Field<FlowButton>(f,"applyButton")),"Native text Undo still restores the draft with Apply reachable / "+dark+" / "+mode);Shot(f,"compact-"+dark+"-"+mode);File.WriteAllText(Path.Combine(root,"compact-geometry-"+dark+"-"+mode+".json"),new JavaScriptSerializer().Serialize(Walk(f).Where(c=>c is Button).Select(c=>new{c.Name,c.Text,c.Bounds,screen=f.PointToClient(c.PointToScreen(Point.Empty)),visible=c.Visible,fullyVisible=RenderedInside(c)}).ToArray()));}}
 static int InkHeight(Bitmap bitmap,int limit){int first=bitmap.Height,last=-1;double ink=(Ui.Ink.R+Ui.Ink.G+Ui.Ink.B)/3.0,muted=(Ui.Muted.R+Ui.Muted.G+Ui.Muted.B)/3.0,threshold=(ink+muted)/2;for(int y=0;y<Math.Min(limit,bitmap.Height);y++)for(int x=0;x<bitmap.Width;x++){Color p=bitmap.GetPixel(x,y);double light=(p.R+p.G+p.B)/3.0;if(ink<muted?light<threshold:light>threshold){first=Math.Min(first,y);last=y;}}return last<first?0:last-first+1;}
 static void CheckPaletteGlyphs(BlockButton block,bool dark){using(var rendered=new Bitmap(block.Width,block.Height))using(var reference=new Bitmap(800,200))using(var g=Graphics.FromImage(reference))using(var font=Ui.Font(10,FontStyle.Bold)){block.DrawToBitmap(rendered,new Rectangle(Point.Empty,block.Size));g.Clear(Ui.Raised);TextRenderer.DrawText(g,block.Text,font,new Rectangle(10,10,780,180),Ui.Ink,TextFormatFlags.Left|TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);int actual=InkHeight(rendered,(int)Math.Round(34*Scale)),expected=InkHeight(reference,reference.Height);Check(expected>0&&Math.Abs(actual-expected)<=1,"Palette title glyphs retain the same full height as an unclipped reference at "+Scale+" / "+dark+" (actual "+actual+", expected "+expected+")");rendered.Save(Path.Combine(root,"palette-title-"+dark+".png"));reference.Save(Path.Combine(root,"palette-title-reference-"+dark+".png"));}}
 static void Check(bool b,string message){checks++;Console.WriteLine((b?"PASS ":"FAIL ")+message);results.Add(new{pass=b,message=message});}
 static void ApplyControlledScale(Form f){f.AutoScaleMode=AutoScaleMode.None;f.Scale(new SizeF(Scale,Scale));}
 static void Dialogs(MainForm owner,bool dark){
  var names=new[]{"guide","export","source","rename","search","commands","test-data"};
  foreach(string name in names){Form dialog=name=="guide"?(Form)new GuideDialog():name=="export"?new ExportDialog(owner.Canvas):name=="source"?new SourceCodeDialog(owner.Project,null,FlowSourceTarget.Python):name=="rename"?new VariableRenameDialog(owner.Project,null):name=="search"?new ProjectSearchDialog(FlowSearch.Capture(owner.Project),null,"Principale"):name=="commands"?new CommandPaletteDialog(new[]{new FlowQuickCommand("Salva","Progetto",()=>true,()=>{})},null,""):(Form)new TestDialog(owner.Project);
   using(dialog){dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-6000,-4000);ApplyControlledScale(dialog);dialog.Show(owner);Pump(400);var buttons=Walk(dialog).OfType<Button>().Where(b=>b.Visible&&b.Enabled).ToArray();Check(buttons.Length>0&&buttons.All(Inside),"Dialog actions fit native containers: "+name+" / "+Scale+" / "+dark);var fields=Walk(dialog).OfType<TextBoxBase>().Where(b=>b.Visible).ToArray();Check(fields.All(b=>b.Width>=40*Scale&&b.Height>=16*Scale),"Dialog fields retain native editing area: "+name+" / "+Scale+" / "+dark);Check(buttons.All(b=>!String.IsNullOrWhiteSpace(b.Text)||!String.IsNullOrWhiteSpace(b.AccessibleName)),"Dialog actions have names: "+name+" / "+Scale+" / "+dark);Shot(dialog,"dialog-"+name+"-"+dark);dialog.Close();}
  }
 }
 static void Shot(Form f,string name){using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(root,name+".png"));}}
 [STAThread]static int Main(string[] args){root=args[0];Scale=Single.Parse(args[1],System.Globalization.CultureInfo.InvariantCulture);Directory.CreateDirectory(root);Application.EnableVisualStyles();UiMotion.SetEnabled(false);float actual=0;
 try{foreach(bool dark in new[]{false,true}){Ui.SetDarkMode(dark,false);using(var f=new MainForm(null,true)){bool compact=Environment.GetEnvironmentVariable("FROCIART_DPI_COMPACT")=="1";f.ShowInTaskbar=compact;f.StartPosition=compact?FormStartPosition.CenterScreen:FormStartPosition.Manual;f.Location=new Point(-5000,-4000);ApplyControlledScale(f);f.Size=new Size((int)(1420*Scale),(int)(900*Scale));f.Show();Pump();using(var g=f.CreateGraphics())actual=g.DpiX;f.EnterEditor();f.SetDocument(Examples.Parity(),null,false);Pump();f.Canvas.SelectNode("check");Pump();
  if(compact){CompactScreen(f,dark);f.SetDocument(DiagramIO.CreateBlank(),null,false);f.Close();continue;}
  f.SetWorkspaceLayout(2,false);Pump();var blocks=Walk(f).OfType<BlockButton>().ToArray();Check(blocks.Length>10&&blocks.All(b=>Math.Abs(b.Width-164*Scale)<=2&&Math.Abs(b.Height-60*Scale)<=2),"Recreated palette blocks retain DPI-scaled geometry at "+Scale+" / "+dark);
  CheckPaletteGlyphs(blocks.First(b=>b.Kind==NodeKind.Start),dark);
  foreach(int width in new[]{1420,1120}){f.Size=new Size((int)(width*Scale),(int)(720*Scale));Pump();var top=Walk(f).Where(c=>c.Name.StartsWith("Task",StringComparison.Ordinal)||c.Name=="QuickCommands").ToArray();Check(top.Length==7&&top.All(Inside),"Task commands remain inside native containers at "+width+" / "+Scale+" / "+dark);
   var commandHost=Field<Panel>(f,"commandHost");Check(commandHost.Height>=Math.Round(58*Scale)-1,"Editor command row retains scaled height after Home to editor at "+Scale+" / "+dark);
   var center=Field<TableLayoutPanel>(f,"workspaceCenter");Check(center.Controls.Cast<Control>().All(Inside),"Diagram column children fit their actual container after shrinking at "+width+" / "+Scale+" / "+dark);
   Check(Field<TableLayoutPanel>(f,"editorBody").Controls.Cast<Control>().All(AncestorsInside),"Palette, diagram and inspector columns fit through all ancestors to the window at "+width+" / "+Scale+" / "+dark);
   Check(top.All(c=>f.ClientRectangle.Contains(new Rectangle(f.PointToClient(c.PointToScreen(Point.Empty)),c.Size))),"Task commands remain entirely inside the actual window at "+width+" / "+Scale+" / "+dark);
   File.WriteAllText(Path.Combine(root,"geometry-"+width+"-"+dark+".json"),new JavaScriptSerializer().Serialize(Walk(f).Where(c=>c.Name.StartsWith("Task",StringComparison.Ordinal)||c.Name=="QuickCommands").Select(c=>new{c.Name,c.Bounds,parent=c.Parent.Bounds,parentClient=c.Parent.ClientSize,headerBounds=c.Parent.Parent.Bounds,headerClient=c.Parent.Parent.ClientSize,formClient=f.ClientSize,shellBounds=f.Controls[0].Bounds,windowPoint=f.PointToClient(c.PointToScreen(Point.Empty)),preferred=c.Parent.PreferredSize}).ToArray()));
   var apply=Field<FlowButton>(f,"applyButton");Check(apply.Visible&&Inside(apply),"Inspector apply remains reachable at "+width+" / "+Scale+" / "+dark);var editor=Field<TextBox>(f,"expression");Check(editor.Visible&&editor.Width>=100*Scale&&editor.Height>=36*Scale,"Condition editor retains a usable native area at "+width+" / "+Scale+" / "+dark);Check(f.Canvas.Width>200*Scale&&f.Canvas.Height>250*Scale,"Diagram remains usable at "+width+" / "+Scale+" / "+dark);
   var overlap=false;for(int i=0;i<top.Length;i++)for(int j=i+1;j<top.Length;j++)if(top[i].Parent==top[j].Parent)overlap|=top[i].Bounds.IntersectsWith(top[j].Bounds);Check(!overlap,"Task command bounds do not overlap at "+width+" / "+Scale+" / "+dark);Shot(f,"editor-"+width+"-"+dark);
  }Dialogs(f,dark);f.SetDocument(DiagramIO.CreateBlank(),null,false);f.Close();}}
  File.WriteAllText(Path.Combine(root,"layout.json"),new JavaScriptSerializer().Serialize(new{status=results.All(x=>(bool)x.GetType().GetProperty("pass").GetValue(x,null))?"PASS_CONTROLLED_DPI_INPUT":"FAIL",checks=checks,inputDpi=96*Scale,actualHdcDpi=actual,osDisplayChanged=false,method="Real WinForms controls scaled in process; production DPI-dependent layout receives controlled test input; fonts scaled to reproduce physical point sizes at native HDC96. Not a changed monitor or a bitmap enlargement.",results=results}));Console.WriteLine("CONTROLLED_DPI_LAYOUT checks="+checks+" input="+(96*Scale)+" HDC="+actual);return 0;
